def make_palindrome(string: str) -> str:
    if not string:
        return ''

    def is_palindrome(s: str) -> bool:
        return s == s[::-1]

    # Find the longest palindromic suffix
    for i in range(len(string)):
        if is_palindrome(string[i:]):
            longest_suffix_length = len(string) - i
            break
    else:
        longest_suffix_length = 0

    # Get the prefix that needs to be reversed and added
    prefix_to_add = string[:-longest_suffix_length] if longest_suffix_length else string
    return string + prefix_to_add[::-1]

